'use client';
import { useState } from 'react';

export function {{component_name}}() {
  const [previews, setPreviews] = useState<{ url: string; name: string }[]>([]);
  function onPick(e: React.ChangeEvent<HTMLInputElement>) {
    const files = Array.from(e.target.files ?? []);
    setPreviews(files.map(f => ({ url: URL.createObjectURL(f), name: f.name })));
  }
  return (
    <div>
      <input type="file" accept="{{accept}}" multiple onChange={onPick} />
      <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
        {previews.map(p => (
          <figure key={p.url}><img src={p.url} alt={p.name} style={{ width:120, height:120, objectFit:'cover' }} /><figcaption>{p.name}</figcaption></figure>
        ))}
      </div>
    </div>
  );
}
